import 'package:flutter/material.dart';
import '../app_state.dart';

class ProfilePage extends StatelessWidget {
 const ProfilePage({super.key});
 @override Widget build(BuildContext context)=>AnimatedBuilder(animation:AppState.instance,builder:(context,_) {final app=AppState.instance;return Scaffold(appBar:AppBar(title:Text(app.isOwner?'Profil Pemilik':'Profil Saya')),body:ListView(padding:const EdgeInsets.all(20),children:[Center(child:CircleAvatar(radius:48,backgroundColor:Colors.orange.shade100,child:Icon(app.isOwner?Icons.storefront:Icons.person,size:50,color:Colors.deepOrange))),const SizedBox(height:12),Center(child:Text(app.name,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold))),Center(child:Text(app.email,style:const TextStyle(color:Colors.grey))),const SizedBox(height:22),Card(child:ListTile(leading:const Icon(Icons.edit_outlined,color:Colors.deepOrange),title:const Text('Edit profil'),subtitle:const Text('Nama, email, telepon, dan alamat'),trailing:const Icon(Icons.chevron_right),onTap:()=>_edit(context))),Card(child:ListTile(leading:Icon(app.isOwner?Icons.storefront:Icons.shopping_bag_outlined,color:Colors.deepOrange),title:Text(app.isOwner?'Mode pemilik restoran':'Mode pembeli'),subtitle:Text(app.isOwner?'Kelola toko dan pesanan':'Jelajahi restoran dan pesan makanan'),trailing:Switch(value:app.isOwner,onChanged:(v)=>app.setOwner(v)))),Card(child:ListTile(leading:const Icon(Icons.location_on_outlined),title:const Text('Alamat pengiriman'),subtitle:Text(app.address))),const SizedBox(height:12),const Text('Catatan: pergantian peran di versi ini merupakan simulasi lokal. Autentikasi dan akun pemilik terverifikasi memerlukan backend.',style:TextStyle(color:Colors.grey,fontSize:12))]));});
 Future<void> _edit(BuildContext context) async {final app=AppState.instance;final name=TextEditingController(text:app.name),email=TextEditingController(text:app.email),phone=TextEditingController(text:app.phone),address=TextEditingController(text:app.address);final key=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Edit profil'),content:Form(key:key,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'Nama'),validator:(v)=>v==null||v.trim().isEmpty?'Nama wajib diisi':null),TextFormField(controller:email,decoration:const InputDecoration(labelText:'Email'),keyboardType:TextInputType.emailAddress,validator:(v)=>v==null||!v.contains('@')?'Email tidak valid':null),TextFormField(controller:phone,decoration:const InputDecoration(labelText:'Nomor telepon'),keyboardType:TextInputType.phone),TextFormField(controller:address,decoration:const InputDecoration(labelText:'Alamat'),maxLines:2)]))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Batal')),FilledButton(onPressed:(){if(key.currentState!.validate())Navigator.pop(ctx,true);},child:const Text('Simpan'))]));if(ok==true){app.name=name.text.trim();app.email=email.text.trim();app.phone=phone.text.trim();app.address=address.text.trim();await app.saveProfile();}name.dispose();email.dispose();phone.dispose();address.dispose();}
}
